var r=class{constructor(){this.timeouts=new Set,this.intervals=new Set;}setTimeout(t,s){let e=setTimeout(()=>{this.timeouts.delete(e),t();},s);return this.timeouts.add(e),e}setInterval(t,s){let e=setInterval(t,s);return this.intervals.add(e),e}clearTimeout(t){t!=null&&(clearTimeout(t),this.timeouts.delete(t));}clearInterval(t){t!=null&&(clearInterval(t),this.intervals.delete(t));}clear(){this.timeouts.forEach(t=>clearTimeout(t)),this.intervals.forEach(t=>clearInterval(t)),this.timeouts.clear(),this.intervals.clear();}};export{r};